  private async getDealContactLinks(
    dealId: string,
    manager: EntityManager = this.dataSource.manager,
  ): Promise<Array<{ contactId: string; role: string | null }>> {
    const links = await manager.find(DealContactLinkEntity, {
      where: { dealId },
      order: {
        createdAt: 'ASC',
      },
    });

    return links.map((link) => ({
      contactId: link.contactId,
      role: link.role,
    }));
  }

  private async hydrateDealsWithContacts(
    deals: DealEntity[],
  ): Promise<DealResponseDto[]> {
    if (deals.length === 0) {
      return [];
    }

    const contactRows = await this.getDealContactRows(deals.map((deal) => deal.id));
    const contactRowsByDealId = new Map<string, DealContactRow[]>();

    for (const row of contactRows) {
      const existingRows = contactRowsByDealId.get(row.dealId) ?? [];
      existingRows.push(row);
      contactRowsByDealId.set(row.dealId, existingRows);
    }

    return deals.map((deal) => {
      const dealContacts = contactRowsByDealId.get(deal.id) ?? [];
      const contacts: DealContactSummary[] = dealContacts.map((contactRow) => ({
        id: contactRow.contactId,
        name: contactRow.contactName,
        role: contactRow.role,
      }));

      return {
        ...deal,
        contacts,
      };
    });
  }

  private async getDealContactRows(dealIds: string[]): Promise<DealContactRow[]> {
    if (dealIds.length === 0) {
      return [];
    }

    return this.dataSource.manager.query<DealContactRow[]>(
      `
        SELECT
          link."dealId" AS "dealId",
          link."contactId" AS "contactId",
          link."role" AS "role",
          contact."name" AS "contactName"
        FROM "deal_contact_links" link
        INNER JOIN "contacts" contact
          ON contact.id = link."contactId"
        WHERE link."dealId" = ANY($1)
        ORDER BY link."dealId", link."createdAt" ASC
      `,
      [dealIds],
    );
  }

  private createValidationError(field: string, messages: string[]): AppException {
    return new AppException({
