jest.setTimeout(30000);

describe('Deal API (e2e)', () => {
  let app: INestApplication;
  let dataSource: DataSource;
  let companySeq = 0;
  let contactSeq = 0;
  let dealSeq = 0;

  beforeAll(async () => {
    await resetDatabaseSchema();
    app = await createTestApp();
    dataSource = app.get(DataSource);
    await truncateBusinessTables(dataSource);
  });

  afterAll(async () => {
    if (app) {
      await app.close();
    }

    await closeTestDataSource();
  });

  it('creates a deal with multiple contacts and roles', async () => {
    const companyId = await createCompany('deal-create');
    const businessOwnerId = await createContact('business-owner', companyId);
    const legalId = await createContact('legal-reviewer', companyId);
    const itLeadId = await createContact('it-lead', companyId);

    const payload = buildDealPayload('create', {
      companyId,
      contactLinks: [
        { contactId: businessOwnerId, role: 'decision-maker' },
        { contactId: legalId, role: 'legal' },
        { contactId: itLeadId, role: 'it' },
      ],
      primaryContactId: businessOwnerId,
      stage: 'proposal',
      expectedCloseDate: '2026-12-10T08:00:00.000Z',
    });

    const createResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    expect(createResponse.body).toMatchObject({
      name: payload.name,
      value: payload.value,
      stage: payload.stage,
      companyId,
      primaryContactId: businessOwnerId,
      expectedCloseDate: payload.expectedCloseDate,
      contacts: [
        {
          id: businessOwnerId,
          role: 'decision-maker',
        },
        {
          id: legalId,
          role: 'legal',
        },
        {
          id: itLeadId,
          role: 'it',
        },
      ],
    });
    expect(createResponse.body).not.toHaveProperty('contactId');

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/deals/${createResponse.body.id}`)
      .expect(200);

    expect(detailResponse.body).toMatchObject({
      id: createResponse.body.id,
      companyId,
      primaryContactId: businessOwnerId,
      company: {
        id: companyId,
      },
    });
    expect(detailResponse.body.contacts).toHaveLength(3);
    expect(detailResponse.body).not.toHaveProperty('contactId');
  });

  it('accepts deals with zero linked contacts', async () => {
    const companyId = await createCompany('deal-no-contacts');
    const payload = buildDealPayload('no-contacts', {
      companyId,
      contactLinks: [],
      primaryContactId: null,
    });

    const createResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    expect(createResponse.body.contacts).toEqual([]);
    expect(createResponse.body.primaryContactId).toBeNull();

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/deals/${createResponse.body.id}`)
      .expect(200);

    expect(detailResponse.body.contacts).toEqual([]);
    expect(detailResponse.body.primaryContactId).toBeNull();
  });

});

