it('replaces deal contacts atomically and keeps prior data on unknown contact', async () => {
  const companyId = await createCompany('deal-replace-contacts');
  const contactA = await createContact('replace-a', companyId);
  const contactB = await createContact('replace-b', companyId);
  const contactC = await createContact('replace-c', companyId);

  const dealId = await createDeal('replace-initial', {
    companyId,
    contactLinks: [
      { contactId: contactA, role: 'owner' },
      { contactId: contactB, role: 'legal' },
    ],
    primaryContactId: contactA,
  });

  const invalidReplaceResponse = await request(app.getHttpServer())
    .post(`/api/deals/${dealId}`)
    .send({
      contactLinks: [
        { contactId: contactC, role: 'it' },
        { contactId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ad', role: 'ghost' },
      ],
      primaryContactId: contactC,
    })
    .expect(404);

  expect(invalidReplaceResponse.body.code).toBe('NOT_FOUND');

  const unchangedDetail = await request(app.getHttpServer())
    .get(`/api/deals/${dealId}`)
    .expect(200);

  expect(unchangedDetail.body.primaryContactId).toBe(contactA);
  expect(unchangedDetail.body.contacts.map((item: { id: string }) => item.id).sort()).toEqual(
    [contactA, contactB].sort(),
  );

  const validReplaceResponse = await request(app.getHttpServer())
    .post(`/api/deals/${dealId}`)
    .send({
      contactLinks: [
        { contactId: contactB, role: 'legal' },
        { contactId: contactC, role: 'it' },
      ],
      primaryContactId: contactC,
    })
    .expect(201);

  expect(validReplaceResponse.body.primaryContactId).toBe(contactC);
  expect(validReplaceResponse.body.contacts.map((item: { id: string }) => item.id).sort()).toEqual(
    [contactB, contactC].sort(),
  );
});

