import { faker } from '@faker-js/faker';
import {
  CompanyEntity,
  CompanyStatus,
  Industry,
} from '../../../modules/company/company.entity';
import { ContactCompanyLinkEntity } from '../../../modules/contact/contact-company-link.entity';
import { ContactEntity } from '../../../modules/contact/contact.entity';
import { DealContactLinkEntity } from '../../../modules/deal/deal-contact-link.entity';
import { DealEntity } from '../../../modules/deal/deal.entity';
import { buildCompany } from '../factories/company.factory';
import { buildContact } from '../factories/contact.factory';
import { buildDeal } from '../factories/deal.factory';
import { SeedContext, SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const DEMO_PREFIX = 'Demo Seed Company';
const STATUSES = [
  CompanyStatus.ACTIVE,
  CompanyStatus.INACTIVE,
  CompanyStatus.PENDING,
] as const;
const INDUSTRIES = [
  Industry.TECHNOLOGY,
  Industry.FINANCE,
  Industry.MANUFACTURING,
  Industry.RETAIL,
  Industry.OTHER,
] as const;
const DEAL_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
  'closed-lost',
] as const;

const daysFromNow = (now: Date, days: number) => {
  const date = new Date(now);
  date.setDate(date.getDate() + days);
  date.setHours(17, 0, 0, 0);

  return date;
};

const createDemoCompanies = async ({ dataSource, now }: SeedContext) => {
  const companyRepository = dataSource.getRepository(CompanyEntity);
  const contactRepository = dataSource.getRepository(ContactEntity);
  const contactCompanyLinkRepository = dataSource.getRepository(
    ContactCompanyLinkEntity,
  );
  const dealRepository = dataSource.getRepository(DealEntity);
  const dealContactLinkRepository = dataSource.getRepository(DealContactLinkEntity);
  let contactsCreated = 0;
  let dealsCreated = 0;
  const companiesWithContacts: Array<{ id: string; contacts: string[] }> = [];

  await cleanupCompaniesByPrefixes({ dataSource, now }, [DEMO_PREFIX]);

  for (let companyIndex = 0; companyIndex < 10; companyIndex += 1) {
    const companyName = `${DEMO_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`;
    const company = await companyRepository.save(
      companyRepository.create(
        buildCompany({
          name: companyName,
          status: STATUSES[companyIndex % STATUSES.length],
          industry: INDUSTRIES[companyIndex % INDUSTRIES.length],
          lastContactedAt: distributeRecentDate(now, companyIndex, 10),
          email: `demo-company-${companyIndex + 1}@baseline.local`,
        }),
      ),
    );
    const contactIds: string[] = [];

    const contactsForCompany = 2 + (companyIndex % 4);

    for (
      let contactIndex = 0;
      contactIndex < contactsForCompany;
      contactIndex += 1
    ) {
      contactsCreated += 1;

      const contact = await contactRepository.save(
        contactRepository.create(
          buildContact({
            name: faker.person.fullName(),
            lastContactedAt: distributeRecentDate(
              now,
              companyIndex + contactIndex,
              14,
            ),
            email: `demo-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
            role: [
              'Decision Maker',
              'User',
              'Finance Reviewer',
              'Technical Buyer',
            ][contactIndex % 4],
          }),
        ),
      );

      await contactCompanyLinkRepository.save(
        contactCompanyLinkRepository.create({
          contactId: contact.id,
          companyId: company.id,
          isPrimary: true,
        }),
      );

      contactIds.push(contact.id);
    }

    companiesWithContacts.push({
      id: company.id,
      contacts: contactIds,
    });
  }

  if (companiesWithContacts[0] && companiesWithContacts[1]) {
    await contactCompanyLinkRepository.save(
      contactCompanyLinkRepository.create({
        contactId: companiesWithContacts[0].contacts[0],
        companyId: companiesWithContacts[1].id,
        isPrimary: false,
      }),
    );
  }

  const multiContactDealCompany = companiesWithContacts.find(
    (company) => company.contacts.length >= 3,
  );

  for (let dealIndex = 0; dealIndex < 12; dealIndex += 1) {
    const companyRef =
      companiesWithContacts[dealIndex % companiesWithContacts.length];
    const stage = DEAL_STAGES[dealIndex % DEAL_STAGES.length];
    const contactId =
      dealIndex % 4 === 0
        ? null
        : (companyRef.contacts[dealIndex % companyRef.contacts.length] ?? null);

    const isThreeContactDeal =
      dealIndex === 1 &&
      multiContactDealCompany &&
      companyRef.id === multiContactDealCompany.id;

    const threeContactLinks =
      isThreeContactDeal && multiContactDealCompany
        ? [
            {
              contactId: multiContactDealCompany.contacts[0],
              role: 'decision-maker',
            },
            {
              contactId: multiContactDealCompany.contacts[1],
              role: 'legal',
            },
            {
              contactId: multiContactDealCompany.contacts[2],
              role: 'it-lead',
            },
          ]
        : [];

    const deal = await dealRepository.save(
      dealRepository.create(
        buildDeal({
          companyId: companyRef.id,
          primaryContactId:
            threeContactLinks.length > 0
              ? threeContactLinks[0].contactId
              : contactId,
          name: `Demo Deal ${String(dealIndex + 1).padStart(2, '0')} ${stage}`,
          stage,
          value: 6_000 + dealIndex * 2_500,
          expectedCloseDate: daysFromNow(now, 10 + dealIndex * 3),
        }),
      ),
    );

    if (threeContactLinks.length > 0) {
      await dealContactLinkRepository.save(
        threeContactLinks.map((link) =>
          dealContactLinkRepository.create({
            dealId: deal.id,
            contactId: link.contactId,
            role: link.role,
          }),
        ),
      );
    } else if (contactId) {
      await dealContactLinkRepository.save(
        dealContactLinkRepository.create({
          dealId: deal.id,
          contactId,
          role: null,
        }),
      );
    }

    dealsCreated += 1;
  }

  return {
    contactsCreated,
    dealsCreated,
  };
};

export const demoSeedScenario: SeedScenario = {
  name: 'demo',
  async run(context) {
    faker.seed(20260703);

    const { contactsCreated, dealsCreated } =
      await createDemoCompanies(context);

    return {
      scenario: 'demo',
      companiesCreated: 10,
      contactsCreated,
      dealsCreated,
      notes: [
        'Creates 10 companies with 2-5 contacts each.',
        'Creates 12 deals across six pipeline stages.',
        'Cycles company status through ACTIVE, INACTIVE, and PENDING.',
        'Distributes lastContactedAt timestamps across the last 30 days.',
      ],
    };
  },
};

