    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "uuid-ossp"');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "pgcrypto"');
    await dataSource.synchronize();
  });

  it('runs migrations and creates new link-table artifacts', async () => {
    await dataSource.runMigrations();

    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_contact_company_links_contact_id',
        'fk_contact_company_links_company_id',
      ]),
    );

    await expect(listIndexNames(dataSource, 'contact_company_links')).resolves.toEqual(
      expect.arrayContaining([
        'idx_contact_company_links_company_id',
        'idx_contact_company_links_contact_id',
        'idx_contact_company_links_primary_per_contact',
      ]),
    );

    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_deal_contact_links_deal_id',
        'fk_deal_contact_links_contact_id',
      ]),
    );

    await expect(listIndexNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining(['idx_deals_primary_contact_id']),
    );
  });

  it('migrates legacy companyId/contactId values into link tables', async () => {
    await dataSource.query('ALTER TABLE "contacts" ADD COLUMN "companyId" uuid');
    await dataSource.query('ALTER TABLE "deals" ADD COLUMN "contactId" uuid');

    const [{ id: companyId }] = await dataSource.query(
      `
        INSERT INTO "companies" ("id", "name", "status", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Legacy Company', '1', NOW(), NOW())
        RETURNING "id"
      `,
    );

    const [{ id: contactId }] = await dataSource.query(
      `
        INSERT INTO "contacts" ("id", "name", "email", "phone", "role", "companyId", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Legacy Contact', 'legacy-contact@test.local', '+1-555-9012', 'User', $1, NOW(), NOW())
        RETURNING "id"
      `,
      [companyId],
    );

    const [{ id: dealId }] = await dataSource.query(
      `
        INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "contactId", "expectedCloseDate", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Legacy Deal', 1000, 'lead', $1, $2, NULL, NOW(), NOW())
        RETURNING "id"
      `,
      [companyId, contactId],
    );

    await dataSource.runMigrations();

    const [contactLink] = await dataSource.query(
      `
        SELECT "contactId", "companyId", "isPrimary"
        FROM "contact_company_links"
        WHERE "contactId" = $1
      `,
      [contactId],
    );

    expect(contactLink).toMatchObject({
      contactId,
      companyId,
      isPrimary: true,
    });

    const [dealLink] = await dataSource.query(
      `
        SELECT "dealId", "contactId", "role"
        FROM "deal_contact_links"
        WHERE "dealId" = $1
      `,
      [dealId],
    );

    expect(dealLink).toMatchObject({
      dealId,
      contactId,
      role: null,
    });

    const [deal] = await dataSource.query(
      `
        SELECT "primaryContactId"
        FROM "deals"
        WHERE "id" = $1
      `,
      [dealId],
    );

    expect(deal.primaryContactId).toBe(contactId);

    await expect(hasColumn(dataSource, 'contacts', 'companyId')).resolves.toBe(false);
    await expect(hasColumn(dataSource, 'deals', 'contactId')).resolves.toBe(false);
  });

  it('is idempotent when run again on migrated schema', async () => {
    await dataSource.runMigrations();

    const [{ id: companyId }] = await dataSource.query(
      `
        INSERT INTO "companies" ("id", "name", "status", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Idempotent Company', '1', NOW(), NOW())
        RETURNING "id"
      `,
    );

    const [{ id: contactId }] = await dataSource.query(
      `
        INSERT INTO "contacts" ("id", "name", "email", "phone", "role", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Idempotent Contact', 'idempotent-contact@test.local', '+1-555-1111', 'User', NOW(), NOW())
        RETURNING "id"
      `,
    );

    await dataSource.query(
      `
        INSERT INTO "contact_company_links" ("contactId", "companyId", "isPrimary")
        VALUES ($1, $2, true)
      `,
      [contactId, companyId],
    );

    const [{ id: dealId }] = await dataSource.query(
      `
        INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "primaryContactId", "expectedCloseDate", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Idempotent Deal', 2000, 'lead', $1, $2, NULL, NOW(), NOW())
        RETURNING "id"
      `,
      [companyId, contactId],
    );

    await dataSource.query(
      `
        INSERT INTO "deal_contact_links" ("dealId", "contactId", "role")
        VALUES ($1, $2, 'owner')
      `,
      [dealId, contactId],
    );

    const migration = new UpgradeContactCompanyAndDealContactLinks20260817000200();
    const queryRunner = dataSource.createQueryRunner();

    try {
      await queryRunner.connect();
      await migration.up(queryRunner);

      const [{ count: contactCompanyLinkCount }] = await dataSource.query(
        `
          SELECT COUNT(*)::int AS count
          FROM "contact_company_links"
          WHERE "contactId" = $1
            AND "companyId" = $2
        `,
        [contactId, companyId],
      );

      const [{ count: dealContactLinkCount }] = await dataSource.query(
        `
          SELECT COUNT(*)::int AS count
          FROM "deal_contact_links"
          WHERE "dealId" = $1
            AND "contactId" = $2
        `,
        [dealId, contactId],
      );

      expect(contactCompanyLinkCount).toBe(1);
      expect(dealContactLinkCount).toBe(1);
    } finally {
      await queryRunner.release();
    }
  });

  it('restores legacy columns when rolling back latest migration', async () => {
