            COUNT(*) AS linked_contact_count,
            COUNT(DISTINCT link."role") AS distinct_role_count
          FROM "deal_contact_links" link
          GROUP BY link."dealId"
          HAVING COUNT(*) >= 3
             AND COUNT(DISTINCT link."role") >= 3
        ) multi_contact_deals
      `,
    );

    expect(companyCount).toBe(10);
    expect(contactCount).toBe(33);
    expect(dealCount).toBe(12);
    expect(distinctDealStageCount).toBeGreaterThanOrEqual(4);
    expect(multiCompanyContactCount).toBeGreaterThanOrEqual(1);
    expect(threeContactDealCount).toBeGreaterThanOrEqual(1);
  });

  it('does not duplicate demo seed rows across reruns', async () => {
    runSeedCommand('npm run db:reset:seed:demo');
    runSeedCommand('npm run db:seed:demo');

    const [{ count: companyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE 'Demo Seed Company%'
      `,
    );
    const [{ count: contactCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contacts"
        WHERE "email" LIKE 'demo-contact-%@baseline.local'
      `,
    );
    const [{ count: dealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "name" LIKE 'Demo Deal%'
      `,
    );

    expect(companyCount).toBe(10);
    expect(contactCount).toBe(33);
    expect(dealCount).toBe(12);
  });

  it('creates edge-case seed data including deals with zero linked contacts', async () => {
    runSeedCommand('npm run db:reset:seed:edge-case');

    const [{ count: companyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE 'Edge Seed Company%'
           OR "name" LIKE 'Edge Seed Company Long Name%'
      `,
    );
    const [{ count: emptyCompanyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies" company
        WHERE company.name = 'Edge Seed Company 00 Empty Contacts'
          AND NOT EXISTS (
            SELECT 1
            FROM "contact_company_links" link
            WHERE link."companyId" = company.id
          )
      `,
    );
    const [{ count: nullFieldCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" = 'Edge Seed Company 01 Missing Fields'
          AND "email" IS NULL
          AND "phone" IS NULL
          AND "website" IS NULL
      `,
    );
    const [{ count: longNameCompanyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE 'Edge Seed Company Long Name%'
          AND LENGTH("name") >= 250
      `,
    );
    const [{ count: maxLengthRoleCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contacts"
        WHERE LENGTH(COALESCE("role", '')) = 100
      `,
    );
    const [{ count: orphanLinkCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contact_company_links" link
        LEFT JOIN "companies" company ON company.id = link."companyId"
        LEFT JOIN "contacts" contact ON contact.id = link."contactId"
        WHERE company.id IS NULL OR contact.id IS NULL
      `,
    );
    const [{ count: edgeDealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "name" LIKE 'Edge Seed Company Deal%'
           OR "name" LIKE 'Edge Seed Company Deal %'
      `,
    );
    const [{ count: zeroContactDealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals" deal
        WHERE NOT EXISTS (
          SELECT 1
          FROM "deal_contact_links" link
          WHERE link."dealId" = deal.id
        )
      `,
    );
    const [{ count: nullExpectedCloseDateCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "expectedCloseDate" IS NULL
      `,
    );

    expect(companyCount).toBe(25);
    expect(emptyCompanyCount).toBe(1);
    expect(nullFieldCount).toBe(1);
    expect(longNameCompanyCount).toBeGreaterThanOrEqual(1);
    expect(maxLengthRoleCount).toBeGreaterThanOrEqual(1);
    expect(orphanLinkCount).toBe(0);
    expect(edgeDealCount).toBeGreaterThanOrEqual(8);
    expect(zeroContactDealCount).toBeGreaterThanOrEqual(1);
    expect(nullExpectedCloseDateCount).toBeGreaterThanOrEqual(1);
  });
});

function runSeedCommand(command: string) {
  execSync(command, {
    cwd: resolve(__dirname, '../'),
    stdio: 'pipe',
  });
