  const contactOptions = contactsQuery.data?.items ?? [];

  const selectedCompany =
    companyOptions.find((company) => company.id === values.companyId) ?? null;

  const selectedContacts = useMemo(
    () =>
      contactOptions.filter((contact) =>
        values.contactLinks.some((link) => link.contactId === contact.id),
      ),
    [contactOptions, values.contactLinks],
  );

  const errors = useMemo(() => {
    const numericValue = Number(values.value);
    const selectedContactIds = new Set(
      values.contactLinks.map((link) => link.contactId),
    );

    return {
      name: !values.name?.trim() ? 'Name is required.' : '',
      value:
        values.value === ''
          ? 'Value is required.'
          : Number.isNaN(numericValue)
            ? 'Value must be a number.'
            : numericValue < 0
              ? 'Value cannot be negative.'
              : '',
      companyId: !values.companyId ? 'Company is required.' : '',
      primaryContactId:
        values.primaryContactId &&
        !selectedContactIds.has(values.primaryContactId)
          ? 'Primary contact must be one of linked contacts.'
          : '',
    };
  }, [
    values.companyId,
    values.contactLinks,
    values.name,
    values.primaryContactId,
    values.value,
  ]);

  const isFormValid =
    !errors.name && !errors.value && !errors.companyId && !errors.primaryContactId;

  useEffect(() => {
    if (!open) {
      return;
    }

    const initialContactLinks = (initialValues?.contacts ?? []).map((contact) => ({
      contactId: contact.id,
      role: contact.role ?? '',
    }));

    const derivedPrimaryContactId =
      initialValues?.primaryContactId ??
      (initialContactLinks.length === 1 ? initialContactLinks[0].contactId : '');

    setValues({
      ...emptyValues,
      ...initialValues,
      value:
        initialValues?.value === undefined || initialValues?.value === null
          ? ''
          : String(initialValues.value),
      contactLinks: initialContactLinks,
      primaryContactId: derivedPrimaryContactId ?? '',
      expectedCloseDate: formatForDatetimeLocal(initialValues?.expectedCloseDate),
    });

    setTouched({
      name: false,
