  const handleContactsChange = (_, contacts) => {
    const existingRoleByContactId = new Map(
      values.contactLinks.map((link) => [link.contactId, link.role ?? '']),
    );

    const nextLinks = contacts.map((contact) => ({
      contactId: contact.id,
      role: existingRoleByContactId.get(contact.id) ?? '',
    }));

    setValues((current) => {
      const nextContactIds = new Set(nextLinks.map((link) => link.contactId));
      const hasCurrentPrimary = nextContactIds.has(current.primaryContactId);
      const nextPrimaryContactId =
        nextLinks.length === 1
          ? nextLinks[0].contactId
          : hasCurrentPrimary
            ? current.primaryContactId
            : '';

      return {
        ...current,
        contactLinks: nextLinks,
        primaryContactId: nextPrimaryContactId,
      };
    });
  };

  const handleRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((link) =>
        link.contactId === contactId ? { ...link, role } : link,
      ),
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({
      name: true,
      value: true,
      companyId: true,
      primaryContactId: true,
    });

    if (!isFormValid) {
      return;
    }

    const payload = {
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage?.trim() || undefined,
      companyId: values.companyId,
      contactLinks: values.contactLinks.map((link) => ({
        contactId: link.contactId,
        role: link.role?.trim() || null,
      })),
      primaryContactId: values.primaryContactId || null,
      expectedCloseDate: values.expectedCloseDate
        ? new Date(values.expectedCloseDate).toISOString()
        : null,
    };

    await onSubmit(payload);
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit}>
          <TextField
            autoFocus
            required
            label="Name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Value"
              type="number"
              inputProps={{ min: 0, step: 0.01 }}
              value={values.value}
              onBlur={handleBlur('value')}
              onChange={handleChange('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
            />

            <TextField
              fullWidth
              select
              label="Stage"
              value={values.stage}
              onChange={handleChange('stage')}
            >
              {stageOptions.map((stage) => (
                <MenuItem key={stage} value={stage}>
                  {stage}
                </MenuItem>
              ))}
            </TextField>
          </Stack>

          <Autocomplete
            fullWidth
            options={companyOptions}
            value={selectedCompany}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyId')}
            onChange={handleCompanyChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <Autocomplete
            multiple
            fullWidth
            options={contactOptions}
            value={selectedContacts}
            loading={contactsQuery.isLoading}
            onChange={handleContactsChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              values.companyId
                ? contactsQuery.isLoading
                  ? 'Loading contacts...'
                  : 'No contacts found for this company'
                : 'Select a company first'
            }
            disabled={!values.companyId}
            renderInput={(params) => (
              <TextField
