  const [searchInput, setSearchInput] = useState('');
  const [stageInput, setStageInput] = useState('');
  const [companyInput, setCompanyInput] = useState('');
  const [listQuery, setListQuery] = useState({
    page: 1,
    pageSize: 10,
  });

  const dealsQuery = useDealList(listQuery);
  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });

  const companyOptions = companiesQuery.data?.items ?? [];

  const companyNameById = useMemo(
    () =>
      Object.fromEntries(
        companyOptions.map((company) => [company.id, company.name]),
      ),
    [companyOptions],
  );

  const handleFormSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createDeal.mutateAsync(payload);
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal created.',
        });
      } else {
        await updateDeal.mutateAsync({
          id: formState.deal.id,
          data: payload,
        });
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal updated.',
        });
      }

      setFormState({ open: false, mode: 'create', deal: null });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Deal request failed.'),
        });
      }
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) {
      return;
    }

    try {
      await deleteDeal.mutateAsync(deleteTarget.id);
      setDeleteTarget(null);
      setFeedback({
        open: true,
        severity: 'success',
        message: 'Deal deleted.',
      });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Delete failed.'),
        });
      }
    }
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();

    setListQuery((current) => ({
      ...current,
      page: 1,
      ...(stageInput ? { stage: stageInput } : { stage: undefined }),
      ...(companyInput ? { companyId: companyInput } : { companyId: undefined }),
    }));
  };

  const handleResetFilters = () => {
    setSearchInput('');
    setStageInput('');
    setCompanyInput('');
    setListQuery({ page: 1, pageSize: listQuery.pageSize });
  };

  const dealPage = dealsQuery.data;
  const dealItems = dealPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Deals"
        searchValue={searchInput}
        onSearchChange={setSearchInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Use filters to query deals"
        filters={(
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
            <TextField
              select
              size="small"
              label="Stage"
              value={stageInput}
              onChange={(event) => setStageInput(event.target.value)}
              sx={{ minWidth: '11rem' }}
            >
              <MenuItem value="">All stages</MenuItem>
              <MenuItem value="lead">lead</MenuItem>
              <MenuItem value="qualified">qualified</MenuItem>
              <MenuItem value="proposal">proposal</MenuItem>
              <MenuItem value="negotiation">negotiation</MenuItem>
              <MenuItem value="closed-won">closed-won</MenuItem>
              <MenuItem value="closed-lost">closed-lost</MenuItem>
            </TextField>

            <TextField
              select
              size="small"
              label="Company"
              value={companyInput}
              onChange={(event) => setCompanyInput(event.target.value)}
              sx={{ minWidth: '14rem' }}
            >
              <MenuItem value="">All companies</MenuItem>
              {companyOptions.map((company) => (
                <MenuItem key={company.id} value={company.id}>
                  {company.name}
                </MenuItem>
              ))}
            </TextField>
          </Stack>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() =>
              setFormState({
                open: true,
                mode: 'create',
                deal: null,
              })
            }
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && dealItems.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try broadening the selected filters."
        pagination={
          dealPage && dealPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={(page) => setListQuery((current) => ({ ...current, page }))}
                onPageSizeChange={(pageSize) =>
                  setListQuery((current) => ({ ...current, page: 1, pageSize }))
                }
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={dealItems}
          companyNameById={companyNameById}
          onDelete={setDeleteTarget}
          onEdit={(deal) =>
            setFormState({
              open: true,
              mode: 'edit',
              deal,
            })
          }
          onView={(deal) => navigate(`/deals/${deal.id}`)}
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', deal: null })}
        onSubmit={handleFormSubmit}

import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';
import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';
import { useContactList } from '../contacts/contactQueries';

const emptyValues = {
  name: '',
  value: '',
  stage: 'lead',
  companyId: '',
  contactLinks: [],
  primaryContactId: '',
  expectedCloseDate: '',
};

const stageOptions = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
  'closed-lost',
];

export function DealFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    name: false,
    value: false,
    companyId: false,
    primaryContactId: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList({
    ...(values.companyId ? { companyId: values.companyId } : {}),
    page: 1,
    pageSize: 100,
  });

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = contactsQuery.data?.items ?? [];

  const selectedCompany =
    companyOptions.find((company) => company.id === values.companyId) ?? null;

  const selectedContacts = useMemo(
    () =>
      contactOptions.filter((contact) =>
        values.contactLinks.some((link) => link.contactId === contact.id),
      ),
    [contactOptions, values.contactLinks],
  );

  const errors = useMemo(() => {
    const numericValue = Number(values.value);
    const selectedContactIds = new Set(
      values.contactLinks.map((link) => link.contactId),
    );

    return {
      name: !values.name?.trim() ? 'Name is required.' : '',
      value:
        values.value === ''
          ? 'Value is required.'
          : Number.isNaN(numericValue)
            ? 'Value must be a number.'
            : numericValue < 0
              ? 'Value cannot be negative.'
              : '',
      companyId: !values.companyId ? 'Company is required.' : '',
      primaryContactId:
        values.primaryContactId &&
        !selectedContactIds.has(values.primaryContactId)
          ? 'Primary contact must be one of linked contacts.'
          : '',
    };
  }, [
    values.companyId,
    values.contactLinks,
    values.name,
    values.primaryContactId,
    values.value,
  ]);

  const isFormValid =
    !errors.name && !errors.value && !errors.companyId && !errors.primaryContactId;

  useEffect(() => {
    if (!open) {
      return;
    }

    const initialContactLinks = (initialValues?.contacts ?? []).map((contact) => ({
      contactId: contact.id,
      role: contact.role ?? '',
    }));

    const derivedPrimaryContactId =
      initialValues?.primaryContactId ??
      (initialContactLinks.length === 1 ? initialContactLinks[0].contactId : '');

    setValues({
      ...emptyValues,
      ...initialValues,
      value:
        initialValues?.value === undefined || initialValues?.value === null
          ? ''
          : String(initialValues.value),
      contactLinks: initialContactLinks,
      primaryContactId: derivedPrimaryContactId ?? '',
      expectedCloseDate: formatForDatetimeLocal(initialValues?.expectedCloseDate),
    });

    setTouched({
      name: false,
      value: false,
      companyId: false,
      primaryContactId: false,
    });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    setValues((current) => ({
      ...current,
      companyId: company?.id || '',
      contactLinks: [],
      primaryContactId: '',
    }));
  };

  const handleContactsChange = (_, contacts) => {
    const existingRoleByContactId = new Map(
      values.contactLinks.map((link) => [link.contactId, link.role ?? '']),
    );

    const nextLinks = contacts.map((contact) => ({
      contactId: contact.id,
      role: existingRoleByContactId.get(contact.id) ?? '',
    }));

    setValues((current) => {
      const nextContactIds = new Set(nextLinks.map((link) => link.contactId));
      const hasCurrentPrimary = nextContactIds.has(current.primaryContactId);
      const nextPrimaryContactId =
        nextLinks.length === 1
          ? nextLinks[0].contactId
          : hasCurrentPrimary
            ? current.primaryContactId
            : '';

      return {
        ...current,
        contactLinks: nextLinks,
        primaryContactId: nextPrimaryContactId,
      };
    });
  };

  const handleRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((link) =>
        link.contactId === contactId ? { ...link, role } : link,
      ),
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({
      name: true,
      value: true,
      companyId: true,
      primaryContactId: true,
    });

    if (!isFormValid) {
      return;
    }

    const payload = {
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage?.trim() || undefined,
      companyId: values.companyId,
      contactLinks: values.contactLinks.map((link) => ({
        contactId: link.contactId,
        role: link.role?.trim() || null,
      })),
      primaryContactId: values.primaryContactId || null,
      expectedCloseDate: values.expectedCloseDate
        ? new Date(values.expectedCloseDate).toISOString()
        : null,
    };

    await onSubmit(payload);
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit}>
          <TextField
            autoFocus
            required
            label="Name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Value"
              type="number"
              inputProps={{ min: 0, step: 0.01 }}
              value={values.value}
              onBlur={handleBlur('value')}
              onChange={handleChange('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
            />

            <TextField
              fullWidth

              fullWidth
              select
              label="Stage"
              value={values.stage}
              onChange={handleChange('stage')}
            >
              {stageOptions.map((stage) => (
                <MenuItem key={stage} value={stage}>
                  {stage}
                </MenuItem>
              ))}
            </TextField>
          </Stack>

          <Autocomplete
            fullWidth
            options={companyOptions}
            value={selectedCompany}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyId')}
            onChange={handleCompanyChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <Autocomplete
            multiple
            fullWidth
            options={contactOptions}
            value={selectedContacts}
            loading={contactsQuery.isLoading}
            onChange={handleContactsChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              values.companyId
                ? contactsQuery.isLoading
                  ? 'Loading contacts...'
                  : 'No contacts found for this company'
                : 'Select a company first'
            }
            disabled={!values.companyId}
            renderInput={(params) => (
              <TextField
                {...params}
                label="Linked Contacts"
                helperText={contactsQuery.isError ? 'Failed to load contacts.' : undefined}
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {contactsQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          {values.contactLinks.length > 0 ? (
            <Stack spacing={1.5}>
              <Typography variant="subtitle2" color="text.secondary">
                Contact Roles
              </Typography>
              {values.contactLinks.map((link) => {
                const contact = contactOptions.find((item) => item.id === link.contactId);

                return (
                  <TextField
                    key={link.contactId}
                    label={`${contact?.name || link.contactId} role (optional)`}
                    value={link.role ?? ''}
                    onChange={(event) =>
                      handleRoleChange(link.contactId, event.target.value)
                    }
                  />
                );
              })}
            </Stack>
          ) : null}

          <TextField
            select
            label="Primary Contact"
            value={values.primaryContactId}
            onBlur={handleBlur('primaryContactId')}
            onChange={handleChange('primaryContactId')}
            error={touched.primaryContactId && Boolean(errors.primaryContactId)}
            helperText={touched.primaryContactId ? errors.primaryContactId : undefined}
            disabled={values.contactLinks.length === 0}
          >
            <MenuItem value="">None</MenuItem>
            {values.contactLinks.map((link) => {
              const contact = contactOptions.find((item) => item.id === link.contactId);
              return (
                <MenuItem key={link.contactId} value={link.contactId}>
                  {contact?.name || link.contactId}
                </MenuItem>
              );
            })}
          </TextField>

          <TextField
            fullWidth
            label="Expected Close Date"
            type="datetime-local"
            InputLabelProps={{ shrink: true }}
            value={values.expectedCloseDate}
            onChange={handleChange('expectedCloseDate')}
          />

          {mode === 'edit' && initialValues?.createdAt ? (
            <TextField
              disabled
              label="Created At"
              value={new Intl.DateTimeFormat('en', {
                dateStyle: 'medium',
                timeStyle: 'short',
              }).format(new Date(initialValues.createdAt))}
            />
          ) : null}

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import Box from '@mui/material/Box';
import Chip from '@mui/material/Chip';
import CircularProgress from '@mui/material/CircularProgress';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import ArrowLeftOutlined from '@ant-design/icons/ArrowLeftOutlined';
import { Link, useParams } from 'react-router-dom';

import MainCard from 'components/MainCard';
import IconButton from 'components/IconButton';
import { isTransportError } from 'api/request';
import formatDate from 'utils/formatDate';
import { useDeal } from './dealQueries';

const stageColors = {
  lead: 'default',
  qualified: 'info',
  proposal: 'warning',
  negotiation: 'secondary',
  'closed-won': 'success',
  'closed-lost': 'error',
};

function DetailRow({ label, value }) {
  return (
    <Stack direction="row" spacing={2} sx={{ justifyContent: 'space-between' }}>
      <Typography color="text.secondary">{label}</Typography>
      <Typography>{value || '—'}</Typography>
    </Stack>
  );
}

function formatCurrency(value) {
  const normalizedValue = Number(value ?? 0);

  if (Number.isNaN(normalizedValue)) {
    return '—';
  }

  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 2,
  }).format(normalizedValue);
}

function DealContacts({ deal }) {
  const contacts = deal?.contacts ?? [];

  if (contacts.length === 0) {
    return <Typography>—</Typography>;
  }

  return (
    <Stack spacing={0.75} sx={{ alignItems: 'flex-end' }}>
      {contacts.map((contact) => (
        <Stack key={contact.id} direction="row" spacing={1} alignItems="center">
          <Typography>
            {contact.name}
            {contact.role ? ` (${contact.role})` : ''}
          </Typography>
          {deal.primaryContactId === contact.id ? (
            <Chip size="small" color="primary" label="Primary" />
          ) : null}
        </Stack>
      ))}
    </Stack>
  );
}

export default function DealDetail() {
  const { id } = useParams();

  const dealQuery = useDeal(id);
  const deal = dealQuery.data;

  return (
    <Stack spacing={2}>
      <IconButton component={Link} to="/deals" aria-label="Back to deals" shape="rounded">
        <ArrowLeftOutlined />
      </IconButton>

      <MainCard title={deal?.name || 'Deal detail'}>
        {dealQuery.isLoading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
            <CircularProgress />
          </Box>
        ) : null}

        {dealQuery.isError && !isTransportError(dealQuery.error) ? (
          <Typography color="error">{dealQuery.error?.message || 'Failed to load deal.'}</Typography>
        ) : null}

        {deal ? (
          <Stack spacing={1.5}>
            <DetailRow label="ID" value={deal.id} />
            <DetailRow label="Company" value={deal.company?.name || deal.companyId} />
            <Stack direction="row" spacing={2} sx={{ justifyContent: 'space-between' }}>
              <Typography color="text.secondary">Contacts</Typography>
              <DealContacts deal={deal} />
            </Stack>
            <DetailRow
              label="Stage"
              value={
                <Chip
                  label={deal.stage || '—'}
                  color={stageColors[deal.stage] || 'default'}
                  size="small"
                />
              }
            />
            <DetailRow label="Value" value={formatCurrency(deal.value)} />
            <DetailRow label="Expected Close" value={formatDate(deal.expectedCloseDate)} />
            <DetailRow label="Created" value={formatDate(deal.createdAt)} />
          </Stack>
        ) : null}
      </MainCard>
    </Stack>
  );
}

import {
  Button,
  Chip,
  IconButton,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import DeleteOutlined from '@ant-design/icons/DeleteOutlined';
import EditOutlined from '@ant-design/icons/EditOutlined';
import EyeOutlined from '@ant-design/icons/EyeOutlined';
import formatDate from 'utils/formatDate';

const stageColors = {
  lead: 'default',
  qualified: 'info',
  proposal: 'warning',
  negotiation: 'secondary',
  'closed-won': 'success',
  'closed-lost': 'error',
};

function formatCurrency(value) {
  const normalizedValue = Number(value ?? 0);

  if (Number.isNaN(normalizedValue)) {
    return '—';
  }

  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 2,
  }).format(normalizedValue);
}

function StageCell({ stage }) {
  if (!stage) {
    return <TableCell>—</TableCell>;
  }

  return (
    <TableCell>
      <Chip
        label={stage}
        color={stageColors[stage] || 'default'}
        size="small"
      />
    </TableCell>
  );
}

function ContactCell({ deal }) {
  const contacts = deal.contacts ?? [];

  if (contacts.length === 0) {
    return <TableCell>—</TableCell>;
  }

  const primaryContact =
    contacts.find((contact) => contact.id === deal.primaryContactId) ?? contacts[0];

  return (
    <TableCell>
      <Stack spacing={0.5}>
        <Typography variant="body2">
          {primaryContact.name}
          {primaryContact.role ? ` (${primaryContact.role})` : ''}
        </Typography>
        {contacts.length > 1 ? (
          <Typography variant="caption" color="text.secondary">
            +{contacts.length - 1} more
          </Typography>
        ) : null}
      </Stack>
    </TableCell>
  );
}

function ActionCell({ deal, onView, onEdit, onDelete }) {
  return (
    <TableCell align="right">
      <Stack direction="row" spacing={1} justifyContent="flex-end">
        <Button
          size="small"
          startIcon={<EyeOutlined />}
          onClick={() => onView(deal)}
        >
          View
        </Button>
        <IconButton onClick={() => onEdit(deal)} aria-label="edit">
          <EditOutlined />
        </IconButton>
        <IconButton color="error" onClick={() => onDelete(deal)} aria-label="delete">
          <DeleteOutlined />
        </IconButton>
      </Stack>
    </TableCell>
  );
}

export function DealTable({ deals, companyNameById, onDelete, onEdit, onView }) {
  return (
    <TableContainer component={Paper} className="crm-table-shell">
      <Table size="small">
        <TableHead>
          <TableRow>
            <TableCell>Deal</TableCell>
            <TableCell>Company</TableCell>
            <TableCell>Contacts</TableCell>
            <TableCell>Stage</TableCell>
            <TableCell>Value</TableCell>
            <TableCell>Expected Close</TableCell>
            <TableCell>Created</TableCell>
            <TableCell align="right">Actions</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {deals.map((deal) => (
            <TableRow key={deal.id} hover>
              <TableCell>
                <Stack spacing={0.5}>
                  <Typography fontWeight={600}>{deal.name}</Typography>
                  <Typography variant="body2" color="text.secondary">
                    {deal.id}
                  </Typography>
                </Stack>
              </TableCell>

              <TableCell>{companyNameById[deal.companyId] || deal.companyId}</TableCell>
              <ContactCell deal={deal} />
              <StageCell stage={deal.stage} />
              <TableCell>{formatCurrency(deal.value)}</TableCell>
              <TableCell>{formatDate(deal.expectedCloseDate)}</TableCell>
              <TableCell>{formatDate(deal.createdAt)}</TableCell>

              <ActionCell
                deal={deal}
                onView={onView}
                onEdit={onEdit}
                onDelete={onDelete}
              />
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
}

import {
  Alert,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Snackbar,
  Stack,
  TextField,
