      page: 1,
      ...(stageInput ? { stage: stageInput } : { stage: undefined }),
      ...(companyInput ? { companyId: companyInput } : { companyId: undefined }),
    }));
  };

  const handleResetFilters = () => {
    setSearchInput('');
    setStageInput('');
    setCompanyInput('');
    setListQuery({ page: 1, pageSize: listQuery.pageSize });
  };

