      <DataTableShell
        title="Deals"
        searchValue={searchInput}
        onSearchChange={setSearchInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Use filters to query deals"
        filters={(
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
            <TextField
              select
              size="small"
              label="Stage"
              value={stageInput}
              onChange={(event) => setStageInput(event.target.value)}
              sx={{ minWidth: '11rem' }}
            >
              <MenuItem value="">All stages</MenuItem>
              <MenuItem value="lead">lead</MenuItem>
              <MenuItem value="qualified">qualified</MenuItem>
              <MenuItem value="proposal">proposal</MenuItem>
              <MenuItem value="negotiation">negotiation</MenuItem>
              <MenuItem value="closed-won">closed-won</MenuItem>
              <MenuItem value="closed-lost">closed-lost</MenuItem>
            </TextField>

            <TextField
              select
              size="small"
              label="Company"
              value={companyInput}
              onChange={(event) => setCompanyInput(event.target.value)}
              sx={{ minWidth: '14rem' }}
            >
              <MenuItem value="">All companies</MenuItem>
              {companyOptions.map((company) => (
                <MenuItem key={company.id} value={company.id}>
                  {company.name}
                </MenuItem>
              ))}
            </TextField>
          </Stack>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() =>
              setFormState({
                open: true,
                mode: 'create',
                deal: null,
              })
            }
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && dealItems.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try broadening the selected filters."
        pagination={
          dealPage && dealPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={(page) => setListQuery((current) => ({ ...current, page }))}
                onPageSizeChange={(pageSize) =>
                  setListQuery((current) => ({ ...current, page: 1, pageSize }))
                }
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={dealItems}
          companyNameById={companyNameById}
          onDelete={setDeleteTarget}
          onEdit={(deal) =>
            setFormState({
              open: true,
              mode: 'edit',
              deal,
            })
          }
          onView={(deal) => navigate(`/deals/${deal.id}`)}
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', deal: null })}
        onSubmit={handleFormSubmit}
      />

      <Dialog open={Boolean(deleteTarget)} onClose={() => setDeleteTarget(null)}>
        <DialogTitle>Delete deal</DialogTitle>
        <DialogContent>
          <Typography>
