import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';
import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';
import { useContactList } from '../contacts/contactQueries';
import {
  CREATE_STAGE_OPTIONS,
  getAllowedTransitionStages,
} from './stageConfig';

const emptyValues = {
  name: '',
  value: '',
  stage: 'lead',
  companyId: '',
  contactLinks: [],
  primaryContactId: '',
  expectedCloseDate: '',
};

export function DealFormDialog({
  initialValues,
  isPending,
  mode,
  onClearSubmitError,
  onClose,
  onSubmit,
  open,
  submitErrorMessage,
}) {
  const [values, setValues] = useState(emptyValues);
  const isEditMode = mode === 'edit';
  const currentStage = initialValues?.stage || 'lead';
  const [touched, setTouched] = useState({
    name: false,
    value: false,
    companyId: false,
    primaryContactId: false,
    expectedCloseDate: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList({
    ...(values.companyId ? { companyId: values.companyId } : {}),
    page: 1,
    pageSize: 100,
  });

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = contactsQuery.data?.items ?? [];

  const selectedCompany =
    companyOptions.find((company) => company.id === values.companyId) ?? null;

  const selectedContacts = useMemo(
    () =>
      contactOptions.filter((contact) =>
        values.contactLinks.some((link) => link.contactId === contact.id),
      ),
    [contactOptions, values.contactLinks],
  );

  const transitionOptions = useMemo(
    () =>
      isEditMode
        ? getAllowedTransitionStages(currentStage, {
            hasLinkedContacts: values.contactLinks.length > 0,
          })
        : [],
    [currentStage, isEditMode, values.contactLinks.length],
  );

  const errors = useMemo(() => {
    const numericValue = Number(values.value);
    const selectedContactIds = new Set(
      values.contactLinks.map((link) => link.contactId),
    );

    return {
      name: !values.name?.trim() ? 'Name is required.' : '',
      value:
        values.value === ''
          ? 'Value is required.'
          : Number.isNaN(numericValue)
            ? 'Value must be a number.'
            : numericValue < 0
              ? 'Value cannot be negative.'
              : '',
      companyId: !values.companyId ? 'Company is required.' : '',
      primaryContactId:
        values.primaryContactId &&
        !selectedContactIds.has(values.primaryContactId)
          ? 'Primary contact must be one of linked contacts.'
          : '',
      expectedCloseDate:
        values.stage === 'negotiation' && !values.expectedCloseDate
          ? 'Expected close date is required for negotiation stage.'
          : '',
    };
  }, [
    values.companyId,
    values.contactLinks,
    values.expectedCloseDate,
    values.name,
    values.primaryContactId,
    values.stage,
    values.value,
  ]);

  const isFormValid =
    !errors.name &&
    !errors.value &&
    !errors.companyId &&
    !errors.primaryContactId &&
    !errors.expectedCloseDate;

  useEffect(() => {
    if (!open) {
      return;
    }

    const initialContactLinks = (initialValues?.contacts ?? []).map((contact) => ({
      contactId: contact.id,
      role: contact.role ?? '',
    }));

    const derivedPrimaryContactId =
      initialValues?.primaryContactId ??
      (initialContactLinks.length === 1 ? initialContactLinks[0].contactId : '');

    setValues({
      ...emptyValues,
      ...initialValues,
      stage:
        mode === 'create'
          ? CREATE_STAGE_OPTIONS.includes(initialValues?.stage)
            ? initialValues.stage
            : 'lead'
          : initialValues?.stage || 'lead',
      value:
        initialValues?.value === undefined || initialValues?.value === null
          ? ''
          : String(initialValues.value),
      contactLinks: initialContactLinks,
      primaryContactId: derivedPrimaryContactId ?? '',
      expectedCloseDate: formatForDatetimeLocal(initialValues?.expectedCloseDate),
    });

    setTouched({
      name: false,
      value: false,
      companyId: false,
      primaryContactId: false,
      expectedCloseDate: false,
    });
    onClearSubmitError?.();
  }, [initialValues, mode, onClearSubmitError, open]);

  const handleChange = (field) => (event) => {
    onClearSubmitError?.();
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    onClearSubmitError?.();
    setValues((current) => ({
      ...current,
      companyId: company?.id || '',
      contactLinks: [],
      primaryContactId: '',
    }));
  };

  const handleContactsChange = (_, contacts) => {
    onClearSubmitError?.();
    const existingRoleByContactId = new Map(
      values.contactLinks.map((link) => [link.contactId, link.role ?? '']),
    );

    const nextLinks = contacts.map((contact) => ({
      contactId: contact.id,
      role: existingRoleByContactId.get(contact.id) ?? '',
    }));

    setValues((current) => {
      const nextContactIds = new Set(nextLinks.map((link) => link.contactId));
      const hasCurrentPrimary = nextContactIds.has(current.primaryContactId);
      const nextPrimaryContactId =
        nextLinks.length === 1
          ? nextLinks[0].contactId
          : hasCurrentPrimary
            ? current.primaryContactId
            : '';

      return {
        ...current,
        contactLinks: nextLinks,
        primaryContactId: nextPrimaryContactId,
      };
    });
  };

  const handleRoleChange = (contactId, role) => {
    onClearSubmitError?.();
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((link) =>
        link.contactId === contactId ? { ...link, role } : link,
      ),
